			function onCmb3SelectionChange(e){
			    var cmb3 = e.control;
			        
			    var dsAddrArea = app.lookup("dsAddrArea");
			    var dsRegionSgg = app.lookup("dsRegionSgg");
			    
			    var rowDatas = dsAddrArea.getRowDataRanged();
			    //console.log("rowDatas", rowDatas);
			    var arrTmp = new Array();
			    dsRegionSgg.clear();
			    
			    for (var i = 0; i < rowDatas.length; i++) {
			        //console.log("ENG_CTPV_NM", rowDatas[i]["ENG_CTPV_NM"], "cmb5.value", cmb5.value);
			        if (rowDatas[i]["ENG_CTPV_NM"] == cmb3.value && arrTmp.indexOf(rowDatas[i]["SGG_CD"]) == -1) {
			            if (rowDatas[i]["SGG_NM"] != null && rowDatas[i]["SGG_NM"] != "") {
			                var newRowData = {"SGG_CD": rowDatas[i]["SGG_CD"], "SGG_NM": rowDatas[i]["SGG_NM"]};
			                //console.log("newRowData", newRowData);
			                dsRegionSgg.pushRowData(newRowData);
			                dsRegionSgg.commit();
			                arrTmp.push(rowDatas[i]["SGG_CD"]);
			            }
			        }
			    }
			    
			    app.lookup("cmb6").value = "";
			}


